import{_ as t,o as n,c as s,a2 as a}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Chinese console layer","description":"","frontmatter":{},"headers":[],"relativePath":"manual/chinese-console.md","filePath":"manual/chinese-console.md"}'),o={name:"manual/chinese-console.md"};function i(d,e,c,l,r,h){return n(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="chinese-console-layer" tabindex="-1">Chinese console layer <a class="header-anchor" href="#chinese-console-layer" aria-label="Permalink to &quot;Chinese console layer&quot;">​</a></h1><p>Open Cube OS keeps every system-visible string ASCII - and still renders Chinese user content, through a dedicated layer under <code>chinese/</code>.</p><h2 id="what-it-is" tabindex="-1">What it is <a class="header-anchor" href="#what-it-is" aria-label="Permalink to &quot;What it is&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>File</th><th>What it does</th></tr></thead><tbody><tr><td>16x16 CJK font</td><td><code>chinese/chinese_font_data.c</code></td><td>bitmap glyphs for the console</td></tr><tr><td>GB encoding</td><td><code>chinese/encoding.c</code></td><td>gb2312 / utf-8 / ascii codecs</td></tr><tr><td>CN console</td><td><code>chinese/console_cn.c</code></td><td>renders CJK rows on the framebuffer</td></tr><tr><td>Renderer</td><td><code>chinese/render_cn.c</code></td><td>glyph raster pipeline</td></tr><tr><td>Pinyin IME</td><td><code>chinese/pinyin_data.c</code> + ime</td><td>syllable resolution and input</td></tr><tr><td>CN TUI apps</td><td><code>tui_cn_*.c</code></td><td>hardware / net / sysinfo in CN</td></tr></tbody></table><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; chinese          (status: font / encoding / render / ime)</span></span>
<span class="line"><span>oc&gt; chinesetest      (full Chinese-support regression suite)</span></span>
<span class="line"><span>oc&gt; font             (list registered fonts + active renderer)</span></span>
<span class="line"><span>oc&gt; font-test        (render a mixed CJK/ASCII sample row)</span></span>
<span class="line"><span>oc&gt; encoding         (codec status: gb2312 / utf-8 / ascii)</span></span>
<span class="line"><span>oc&gt; encoding-test    (quick codec round-trip check)</span></span>
<span class="line"><span>oc&gt; ime              (pinyin IME status)</span></span>
<span class="line"><span>oc&gt; ime -i           (interactive pinyin input on the console line)</span></span>
<span class="line"><span>oc&gt; lang             (language console switch)</span></span></code></pre></div><h2 id="the-design-rule" tabindex="-1">The design rule <a class="header-anchor" href="#the-design-rule" aria-label="Permalink to &quot;The design rule&quot;">​</a></h2><ul><li><strong>System strings are ASCII</strong>: command names, prompts, boot messages, help text - the firmware/hardware compatibility contract (see <code>CONTRIBUTING.md</code> ground rule 1).</li><li><strong>User content may be anything</strong>: filenames, file contents, editor buffers, network payloads - and the Chinese layer renders them on the console and in the TUI.</li></ul><p>So a terminal without CJK fonts still gets a fully usable system; with the layer on, mixed-language content displays correctly.</p><h2 id="build-configuration" tabindex="-1">Build configuration <a class="header-anchor" href="#build-configuration" aria-label="Permalink to &quot;Build configuration&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>make CONFIG_CHINESE=n     (also forces CONFIG_TUI=n)</span></span></code></pre></div><p>The off-path is real code: <code>console_cn</code> routes to the ASCII equivalents in <code>screen_console</code>, and the configurator&#39;s generated header maps the disabled calls to those equivalents. A <code>CONFIG_CHINESE=n CONFIG_TUI=n</code> build boots with 216 commands (233 - 17 Chinese/TUI commands) - the full config boots 233.</p>`,12)])])}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
